<script lang="ts">
  import { untrack } from 'svelte';
  import ProjectShell from '$lib/components/ProjectShell.svelte';
  import ProjectEntryForm from '$lib/components/ProjectEntryForm.svelte';
  import DatePicker from '$lib/components/DatePicker.svelte';
  import { enhance } from '$app/forms';
  import { page } from '$app/state';
  import { handleInvestmentSubmit } from '$lib/investments/feedback';
  import { projectMoney, classificationLabel, fundingLabel } from '$lib/projects';
  import { creditMinor, creditDecimal } from '$lib/credit';
  import { ArrowLeft, ArrowUpRight, Check, Link2, Plus, WalletCards } from 'lucide-svelte';
  import type { PageData, ActionData } from './$types';
  let { data, form }: { data: PageData; form: ActionData } = $props();
  const project = $derived(data.project);
  const accounts = $derived(data.accounts.filter((a) => a.wallet_group_id === project?.wallet_group_id));
  let selectedIds = $state<string[]>([]);
  let fundingKind = $state('contribution');
  let destinationId = $state('');
  let fundingDate = $state(untrack(() => data.today));
  const destination = $derived(accounts.find((a) => a.id === destinationId));
  const sources = $derived(data.accounts.filter((a) => a.active && a.wallet_group_id !== project?.wallet_group_id && a.currency === destination?.currency));
  const accountLabel = (id: string | null) => data.accounts.find((a) => a.id === id)?.label ?? 'External source';
  const outstanding = (currency: string) => creditDecimal(data.loans.filter((loan) => loan.currency === currency).reduce((n, loan) => n + creditMinor(loan.outstanding), 0n));
  function pageLink(key: string, number: number, anchor: string) { const params = new URLSearchParams(page.url.searchParams); params.set(key, String(number)); return `?${params.toString()}#${anchor}`; }
</script>
<svelte:head><title>{project?.name ?? 'Project'} - Homwe</title></svelte:head>
<ProjectShell title={project?.name ?? 'Project'}>
  <a class="project-back" href="/projects"><ArrowLeft size={16}/> Projects</a>
  {#if data.loadError}<div class="setup-banner" role="alert"><div><strong>Project data is unavailable</strong><p>Please refresh. If Projects has just been installed, the database update needs to be applied.</p><a href="/wallets">Your wallets</a></div></div>{/if}
  {#if form?.message}<p class="form-alert" role={form?.success ? 'status' : 'alert'}>{form.message}</p>{/if}
  {#if project && !data.loadError}
    <section class="welcome-row"><div><p class="eyebrow">{!project.setup_completed ? 'Opening setup' : project.status === 'completed' ? 'Completed project' : 'Project workspace'}</p><h1>{project.name}</h1><p class="welcome-copy">{project.description || 'Funding, costs, and revenue. One clear view.'}</p><a class="project-wallet" href={`/transactions?wallet=${project.wallet_group_id}`}><Link2 size={15}/> {project.walletName} <ArrowUpRight size={14}/></a></div>{#if project.setup_completed && project.status === 'active' && project.walletActive}<a class="primary-button" href="#daily-entry"><Plus size={17}/> Record activity</a>{/if}</section>
    {#if !project.walletActive}<p class="form-alert">The linked wallet is archived. Restore it in <a href="/settings">Settings</a> before adding activity.</p>{/if}
    {#if !project.setup_completed}<section class="setup-card"><p class="eyebrow">A clean starting point</p><h2>Bring your project up to date</h2><ol><li><Check size={16}/> Wallet connected. Existing cash is captured as an opening snapshot.</li><li>Choose recorded wallet expenses and revenue to carry over below.</li><li>Add history-only costs or revenue that were never recorded, then finish setup.</li></ol><p>Both opening-history options leave cash unchanged. Check that wallet cash matches the money actually available before finishing. If old activity needs to change cash, record it in Transactions first, then classify it here. After setup, daily entries update both the project and its wallet.</p><form method="POST" action="?/finish_setup" use:enhance={handleInvestmentSubmit}><button class="primary-button" type="submit"><Check size={17}/> Finish setup and start daily tracking</button></form><small>You can skip opening history now and add it later.</small></section>{/if}

    <section class="section-block"><div class="section-heading"><div><p class="eyebrow">Project position</p><h2>Cash and performance</h2><p class="section-caption">Project reports include classified wallet activity and history-only entries. USD and ZiG stay separate.</p></div></div>
      <div class="project-totals">{#each project.totals as total}<article class="currency-position"><div class="cash-position"><span>{total.currency === 'ZIG' ? 'ZiG' : total.currency} / wallet cash now</span><strong>{projectMoney(total.cash, total.currency)}</strong><small>Actual linked wallet balance</small></div><dl><div><dt>Capital expenditure</dt><dd>{projectMoney(total.capex, total.currency)}</dd></div><div><dt>Operating expenditure</dt><dd>{projectMoney(total.opex, total.currency)}</dd></div><div><dt>Revenue earned</dt><dd>{projectMoney(total.revenue, total.currency)}</dd></div><div class="surplus"><dt>Revenue less operating costs</dt><dd>{projectMoney(total.operatingSurplus, total.currency)}</dd></div><div><dt>Outstanding wallet credit</dt><dd>{projectMoney(outstanding(total.currency), total.currency)}</dd></div></dl></article>{/each}</div>
      <p class="project-note">Funding and loan principal are separate from revenue. Capital costs are shown separately from operating surplus; no depreciation or tax calculation is included.</p>
      {#if data.unclassifiedCount}<a class="review-callout" href="#wallet-history">{data.unclassifiedCount} wallet {data.unclassifiedCount === 1 ? 'entry is' : 'entries are'} not yet classified in this project's cost/revenue reports. Review activity <ArrowUpRight size={15}/></a>{/if}
    </section>

    <section class="section-block" id="wallet-history"><div class="section-heading"><div><p class="eyebrow">Use your existing records</p><h2>{project.setup_completed ? 'Classify wallet activity' : 'Carry over wallet history'}</h2><p class="section-caption">Select only the entries that belong to this project. Importing classifies the existing records without copying them or changing cash.</p></div></div>
      {#if data.unclassified.length}<form method="POST" action="?/classify" use:enhance={handleInvestmentSubmit}>
        <div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>Include</th><th>Date / activity</th><th>Account</th><th>Amount</th><th>Project classification</th></tr></thead><tbody>{#each data.unclassified as row}<tr><td><input class="history-checkbox" type="checkbox" name="transaction_id" value={row.id} bind:group={selectedIds} aria-label={`Include ${row.description || row.kind} on ${row.occurred_at.slice(0, 10)}`}/></td><td><strong>{row.description || (row.kind === 'income' ? 'Income' : 'Spending')}</strong><small class="history-date">{row.occurred_at.slice(0, 10)}</small></td><td>{accountLabel(row.account_id)}</td><td>{projectMoney(row.amount, data.accounts.find((a) => a.id === row.account_id)?.currency ?? 'USD')}</td><td><label><span class="visually-hidden">Classification for {row.description || row.kind}</span><select name={`classification_${row.id}`} required={selectedIds.includes(row.id)} disabled={!selectedIds.includes(row.id)}><option value="">Choose classification</option>{#if row.kind === 'income'}<option value="revenue">Revenue</option><option value="funding">Grant / external funding</option>{:else}<option value="capex">Capital expenditure</option><option value="opex">Operating expenditure</option>{/if}</select></label></td></tr>{/each}</tbody></table></div>
        <div class="history-actions"><p>{selectedIds.length} selected. Transfers and funding receipts are excluded from this list.</p><button class="primary-button" type="submit" disabled={!selectedIds.length}>Carry over selected entries</button></div>
      </form>{:else}<div class="empty-card"><Check size={24}/><h3>Nothing waiting for classification</h3><p>Unclassified income and expenses from the linked wallet will appear here.</p></div>{/if}
      {#if data.activityPages > 1}<nav class="project-pagination" aria-label="Wallet activity pages">{#if data.activityPage > 1}<a href={pageLink('activity_page',data.activityPage-1,'wallet-history')}>Previous</a>{/if}<span>Page {data.activityPage} of {data.activityPages}</span>{#if data.activityPage < data.activityPages}<a href={pageLink('activity_page',data.activityPage+1,'wallet-history')}>Next</a>{/if}</nav>{/if}
    </section>

    <section class="section-block" id="opening-history"><details open={!project.setup_completed}><summary class="section-summary">Add unrecorded opening costs or revenue</summary><p class="section-caption">Only use this for activity missing from the wallet ledger. Entries are included in project reports but never change wallet balances.</p><ProjectEntryForm historical accounts={accounts} categories={data.categories} requestId={data.requestIds.historical} startedOn={project.started_on} today={data.today}/></details></section>

    {#if project.setup_completed && project.status === 'active' && project.walletActive}
      <section class="section-block" id="daily-entry"><div class="section-heading"><div><p class="eyebrow">Daily capture</p><h2>Record project activity</h2><p class="section-caption">One entry updates the wallet and the project. Use Funding below for contributions, grants, and loans.</p></div></div><ProjectEntryForm accounts={accounts} categories={data.categories} requestId={data.requestIds.record} startedOn={project.started_on} today={data.today}/></section>
      <section class="section-block" id="add-funding"><div class="section-heading"><div><p class="eyebrow">Keep it moving</p><h2>Add funding</h2><p class="section-caption">Contributions move existing cash. Loans also create a repayment obligation. External funding records new money received.</p></div></div>
        <form method="POST" action="?/fund" class="feature-form" use:enhance={handleInvestmentSubmit}>
          <input type="hidden" name="request_id" value={data.requestIds.fund}/>
          <label>Funding type<select name="kind" bind:value={fundingKind}><option value="contribution">Wallet contribution (not repayable)</option><option value="loan">Loan from another wallet</option><option value="grant">Grant / external funding received</option></select></label>
          <label>Receive into project account<select name="account_id" bind:value={destinationId} required><option value="">Choose project account</option>{#each accounts.filter((a) => a.active) as account}<option value={account.id}>{account.label}</option>{/each}</select></label>
          {#if fundingKind !== 'grant'}<label>Fund from<select name="source_account_id" required disabled={!destinationId}><option value="">Choose a same-currency wallet account</option>{#each sources as account}<option value={account.id}>{account.label} / available {projectMoney(account.balance, account.currency)}</option>{/each}</select></label>{:else}<label>Income category<select name="category_id" required><option value="">Choose funding category</option>{#each data.categories.filter((c) => c.kind === 'income') as category}<option value={category.id}>{category.name}</option>{/each}</select></label>{/if}
          <label>Amount<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" required/></label>
          <label>Funding date<DatePicker name="occurred_on" bind:value={fundingDate} min={project.started_on} max={data.today} required/></label>
          {#if fundingKind === 'loan'}<label>Repay by<DatePicker name="due_on" min={fundingDate} required/></label>{/if}
          <label class="form-wide">Funding source / note<input name="description" maxlength="240" placeholder={fundingKind === 'grant' ? 'e.g. BeVisioneers grant, instalment 2' : 'e.g. Personal contribution for equipment'} required/></label>
          <div class="form-wide form-footer"><p>Wallet-to-wallet funding uses matching currencies. Funding is not project sales revenue.</p><button class="primary-button" type="submit">{fundingKind === 'loan' ? 'Transfer and create loan' : 'Record funding'}</button></div>
        </form>
      </section>
    {/if}

    <section class="section-block"><div class="section-heading"><div><p class="eyebrow">Where the money came from</p><h2>Funding record</h2><p class="section-caption">Opening cash is a snapshot at connection. Actual funding receipts and loans are shown separately from that snapshot.</p></div></div><div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>Date</th><th>Type / source</th><th>Account</th><th>Amount</th><th></th></tr></thead><tbody>{#each data.funding as row}<tr><td>{row.occurred_on}</td><td><strong>{fundingLabel(row.kind)}</strong><small class="history-date">{row.source_account_id ? accountLabel(row.source_account_id) : row.description}</small></td><td>{accountLabel(row.account_id)}</td><td>{projectMoney(row.amount, row.currency)}</td><td>{#if row.kind === 'grant' && !row.request_id}<form method="POST" action="?/unclassify_funding" use:enhance={handleInvestmentSubmit}><input type="hidden" name="funding_id" value={row.id}/><button class="text-button" type="submit">Unclassify receipt</button></form>{/if}</td></tr>{/each}</tbody></table></div></section>

    <section class="section-block" id="project-loans"><div class="section-heading"><div><p class="eyebrow">Repayable funding</p><h2>Project loans</h2><p class="section-caption">Includes existing credit received into this wallet. Repayments return principal to the original lending wallet.</p></div><a href="/credit">All credit</a></div>
      {#each data.loans as loan}<article class="loan-row"><div><h3>{loan.name}</h3><p>{accountLabel(loan.lending_account_id)} / due {loan.due_on}</p><strong>{projectMoney(loan.outstanding, loan.currency)} outstanding</strong><span class="loan-status">{loan.status}</span></div>
        {#if loan.kind === 'internal' && loan.status !== 'Repaid' && project.setup_completed && project.status === 'active' && project.walletActive}<details><summary>Record repayment</summary><form method="POST" action="?/repay" class="feature-form" use:enhance={handleInvestmentSubmit}><input type="hidden" name="credit_id" value={loan.id}/><input type="hidden" name="request_id" value={loan.requestId}/><label>Pay from project<select name="account_id" required><option value="">Choose project account</option>{#each accounts.filter((a) => a.active && a.currency === loan.currency && a.id !== loan.lending_account_id) as account}<option value={account.id}>{account.label}</option>{/each}</select></label><label>Principal repaid<input name="amount" type="number" min="0.01" step="0.01" max={loan.remainingPrincipal} required/></label><label>Payment date<DatePicker name="occurred_on" value={data.today} min={loan.borrowed_on > project.started_on ? loan.borrowed_on : project.started_on} max={data.today} required/></label><button class="primary-button" type="submit">Record repayment</button></form></details>{:else if loan.kind !== 'internal'}<a href="/credit">Manage external loan and charges</a>{/if}
      </article>{:else}<p class="section-caption">No project loans. New wallet loans appear here and in Credit.</p>{/each}
    </section>

    <section class="section-block" id="project-history"><div class="section-heading"><div><p class="eyebrow">Costs and earnings</p><h2>Project activity</h2><p class="section-caption">{data.entryCount} classified entries. History-only records do not affect wallet cash.</p></div></div>
      {#if data.entries.length}<div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>Date / description</th><th>Classification</th><th>Source</th><th>Amount</th><th></th></tr></thead><tbody>{#each data.entries as entry}<tr><td><strong>{entry.description}</strong><small class="history-date">{entry.occurred_on}</small></td><td>{classificationLabel(entry.classification)}</td><td>{entry.transaction_id ? 'Wallet ledger' : 'Opening history only'}</td><td>{projectMoney(entry.amount, entry.currency)}</td><td><form method="POST" action="?/remove_entry" use:enhance={handleInvestmentSubmit}><input type="hidden" name="entry_id" value={entry.id}/><button class="text-button" type="submit" aria-label={`Remove project classification for ${entry.description}`}>{entry.transaction_id ? 'Unclassify' : 'Remove history'}</button></form></td></tr>{/each}</tbody></table></div><p class="project-note">Removing a project classification does not delete its wallet transaction.</p>{:else}<p class="section-caption">Add opening history or record your first project entry.</p>{/if}
      {#if data.entryPages > 1}<nav class="project-pagination" aria-label="Project activity pages">{#if data.entryPage > 1}<a href={pageLink('entry_page',data.entryPage-1,'project-history')}>Previous</a>{/if}<span>Page {data.entryPage} of {data.entryPages}</span>{#if data.entryPage < data.entryPages}<a href={pageLink('entry_page',data.entryPage+1,'project-history')}>Next</a>{/if}</nav>{/if}
    </section>
    <section class="section-block"><details><summary class="section-summary">Project settings</summary><form method="POST" action="?/update" class="feature-form" use:enhance={handleInvestmentSubmit}><label>Project name<input name="name" maxlength="80" value={project.name} required/></label><label>Status<select name="status" value={project.status}><option value="active">Active</option><option value="completed">Completed</option></select></label><label class="form-wide">Description<input name="description" maxlength="1000" value={project.description}/></label><div class="form-wide form-footer"><p>Completing a project preserves its wallet and history. Reopen it to record further daily activity.</p><button class="primary-button" type="submit">Save project settings</button></div></form></details></section>
  {/if}
</ProjectShell>
<style>
  .project-back,.project-wallet { display: inline-flex; align-items: center; gap: 8px; color: var(--muted); text-decoration: none; font-size: .85rem; }
  .project-back { margin: 8px 0 24px; } .project-wallet { margin-top: 12px; color: var(--accent); }
  h1 { overflow-wrap: anywhere; }
  .setup-card { border: 1px solid var(--accent); border-radius: 18px; padding: 24px; margin: 0 0 32px; background: var(--accent-soft); }
  .setup-card h2 { margin: 0 0 16px; } .setup-card ol { display: grid; gap: 12px; padding-left: 20px; font-size: .9rem; line-height: 1.5; }
  .setup-card li :global(svg) { vertical-align: middle; } .setup-card p,.setup-card small { color: var(--muted); line-height: 1.6; font-size: .8rem; } .setup-card small { display: block; margin-top: 12px; }
  .project-totals { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,390px),1fr)); gap: 20px; }
  .currency-position { padding: 24px; border-radius: 18px; border: 1px solid var(--line); background: var(--surface); }
  .cash-position { display: grid; gap: 9px; margin-bottom: 22px; } .cash-position span,.cash-position small { color: var(--muted); font-size: .8rem; } .cash-position strong { font-size: clamp(1.8rem,3vw,2.4rem); letter-spacing: -1px; overflow-wrap: anywhere; }
  dl { display: grid; gap: 14px; margin: 0; } dl>div { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-size: .85rem; } dt { color: var(--muted); } dd { margin: 0; text-align: right; }
  .surplus { padding-top: 14px; border-top: 1px solid var(--line); } .project-note { font-size: .75rem; line-height: 1.6; color: var(--muted); }
  .review-callout { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 16px; margin-top: 16px; border: 1px solid var(--line); border-radius: 12px; color: var(--accent); background: var(--accent-soft); font-size: .85rem; text-decoration: none; }
  .history-checkbox { width: 20px; height: 20px; margin: 0; } .history-date { display: block; margin-top: 6px; color: var(--muted); font-size: .75rem; }
  .history-actions { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 16px; align-items: center; margin: 18px 0; } .history-actions p { color: var(--muted); font-size: .8rem; }
  .ledger-table select { min-width: 185px; margin: 0; } .project-pagination { display: flex; justify-content: flex-end; gap: 20px; align-items: center; padding: 16px 0; font-size: .85rem; }
  .section-summary { cursor: pointer; font-size: 1.15rem; font-weight: 700; padding: 8px 0 18px; } .loan-row { padding: 20px; border: 1px solid var(--line); border-radius: 16px; margin-bottom: 16px; background: var(--surface); }
  .loan-row h3 { margin: 0; } .loan-row p { color: var(--muted); font-size: .85rem; } .loan-row details { margin-top: 20px; } .loan-row summary { cursor: pointer; color: var(--accent); padding: 10px 0; } .loan-status { display: inline-block; margin-left: 12px; color: var(--muted); font-size: .75rem; }
  .visually-hidden { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
  @media (max-width: 540px) { .currency-position,.setup-card { padding: 18px; } dl>div { font-size: .8rem; } .history-actions .primary-button { width: 100%; } .project-pagination { justify-content: center; } }
</style>
